package com.bmscompanion.app.data.wdp

/**
 * The designer's own values for the controls of Weapon Delivery Planner's DTC page (`cntDTC`): each control's kind,
 * parent, text, the flags it starts with (v: hidden, e: disabled, r: read-only, k: checked), a masked box's mask,
 * prompt and text format, an up/down box's maximum and decimal places, and a list's items. The page's logic reads
 * them (a masked box's text goes through its mask; a list's selection is an index into its items), so they are the
 * starting state of [DtcPage]. Read out of Falcas's layout; generated, not written by hand.
 */
internal object DtcDesigner {
    class Designed(
        val name: String, val kind: Char, val parent: String, val text: String?, val flags: String,
        val mask: String, val prompt: String, val format: String, val maximum: Int?, val decimals: Int, val items: List<String>,
    )

    val all: Map<String, Designed> by lazy {
        val m = LinkedHashMap<String, Designed>()
        for (chunk in CHUNKS) for (line in chunk.split('\n')) {
            if (line.isEmpty()) continue
            val f = line.split('\u0001')
            m[f[0]] = Designed(
                f[0], f[1][0], f[2], if (f[3] == "\u0005") null else f[3], f[4], f[5], f[6], f[7],
                f[8].toIntOrNull(), f[9].toIntOrNull() ?: 0, if (f[10].isEmpty()) emptyList() else f[10].split('\u0002'),
            )
        }
        m
    }

